import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../state/providers.dart';
class FamilyListScreen extends ConsumerWidget { const FamilyListScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final families = ref.watch(familiesProvider); return Scaffold(appBar: AppBar(title: const Text('Your Families'), actions: [DropdownButton<String>(value: 'owner', items: const [DropdownMenuItem(value: 'owner', child: Text('Owner')), DropdownMenuItem(value: 'editor', child: Text('Editor')), DropdownMenuItem(value: 'viewer', child: Text('Viewer'))], onChanged: (v) => ref.read(repositoryProvider).switchActiveUserRole(v!))]), floatingActionButton: FloatingActionButton.extended(onPressed: () => context.go('/family/new'), icon: const Icon(Icons.add), label: const Text('Create Family')), body: families.when(data: (list) => ListView(children: [for (final f in list) Card(child: ListTile(title: Text(f.name), subtitle: Text('${f.memberUserIds.length} collaborators'), trailing: const Icon(Icons.chevron_right), onTap: () => context.go('/family/${f.id}/tree')))]), loading: () => const Center(child: CircularProgressIndicator()), error: (e, _) => Text('$e'))); }}
